	"log"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

var (
	applyToGenerated = flag.Bool("apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	companyPrefixes  = flag.String("company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	excludes         = flag.String("excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
	filePath         = flag.String("file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	formatFlag       = flag.Bool("format", false, "Option will perform additional formatting. Optional parameter.")
	importsOrder     = flag.String("imports-order", "std,general,company,project", "Your imports groups can be sorted in your way. \nstd - std import group; \ngeneral - libs for general purpose; \ncompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \nproject - your local project dependencies;\nblanked - imports with \"_\" alias;\ndotted - imports with \".\" alias.\nOptional parameter.")
	listDiff         = flag.Bool("list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	localFlag        = flag.String("local", "", "Deprecated")
	outputFlag       = flag.String("output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	projectNameFlag  = flag.String("project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	recursiveFlag    = flag.Bool("recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	rmUnused         = flag.Bool("rm-unused", false, "Remove unused imports. Optional parameter.")
	separateNamed    = flag.Bool("separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	setAlias         = flag.Bool("set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	setExitStatus    = flag.Bool("set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
	useCache         = flag.Bool("use-cache", false, "Use cache to improve performance. Optional parameter.")
	versionFlag      = flag.Bool("version", false, "Show version information")
	versionOnlyFlag  = flag.Bool("version-only", false, "Show only the version string")
)

const versionStr = "3.0.0-20260611193416-a37f51062178"

var stdPackages map[string]bool

func init() {
	stdPackages = loadStdPackages()
}

func loadStdPackages() map[string]bool {
	m := make(map[string]bool)
	// try go list std
	cmd := exec.Command("go", "list", "std")
	out, err := cmd.Output()
	if err == nil {
		for _, line := range strings.Split(string(out), "\n") {
			line = strings.TrimSpace(line)
			if line != "" {
				m[line] = true
			}
		}
		if len(m) > 0 {
			return m
		}
	}
	// fallback: common std packages (partial, dot heuristic will be used as fallback? but we need real list)
	// Use dot heuristic as fallback: if no dot, std? But C should be general.
	// For fallback, hardcode major std packages
	fallback := []string{
		"archive/tar", "archive/zip", "bufio", "bytes", "cmp", "compress/bzip2", "compress/flate", "compress/gzip", "compress/lzw", "compress/zlib",
		"container/heap", "container/list", "container/ring", "context", "crypto", "crypto/aes", "crypto/cipher", "crypto/des", "crypto/dsa", "crypto/ecdh", "crypto/ecdsa", "crypto/ed25519", "crypto/elliptic", "crypto/hmac", "crypto/md5", "crypto/rand", "crypto/rc4", "crypto/rsa", "crypto/sha1", "crypto/sha256", "crypto/sha512", "crypto/subtle", "crypto/tls", "crypto/x509",
		"database/sql", "database/sql/driver", "debug/buildinfo", "debug/dwarf", "debug/elf", "debug/gosym", "debug/macho", "debug/pe", "debug/plan9obj",
		"embed", "encoding", "encoding/ascii85", "encoding/asn1", "encoding/base32", "encoding/base64", "encoding/binary", "encoding/csv", "encoding/gob", "encoding/hex", "encoding/json", "encoding/pem", "encoding/xml",
		"errors", "expvar", "flag", "fmt", "go/ast", "go/build", "go/constant", "go/doc", "go/format", "go/importer", "go/parser", "go/printer", "go/scanner", "go/token", "go/types", "hash", "hash/adler32", "hash/crc32", "hash/crc64", "hash/fnv", "hash/maphash", "html", "html/template", "image", "image/color", "image/draw", "image/gif", "image/jpeg", "image/png", "index/suffixarray", "io", "io/fs", "io/ioutil", "iter", "log", "log/slog", "maps", "math", "math/big", "math/bits", "math/cmplx", "math/rand", "math/rand/v2", "mime", "mime/multipart", "mime/quotedprintable", "net", "net/http", "net/http/cgi", "net/http/cookiejar", "net/http/fcgi", "net/http/httptest", "net/http/httptrace", "net/http/httputil", "net/http/pprof", "net/mail", "net/netip", "net/rpc", "net/rpc/jsonrpc", "net/smtp", "net/textproto", "net/url", "os", "os/exec", "os/signal", "os/user", "path", "path/filepath", "plugin", "reflect", "regexp", "regexp/syntax", "runtime", "runtime/cgo", "runtime/debug", "runtime/metrics", "runtime/pprof", "runtime/race", "runtime/trace", "slices", "sort", "strconv", "strings", "structlog", "sync", "sync/atomic", "syscall", "testing", "testing/fstest", "testing/iotest", "testing/quick", "testing/slogtest", "text/scanner", "text/tabwriter", "text/template", "text/template/parse", "time", "time/tzdata", "unicode", "unicode/utf16", "unicode/utf8", "unsafe",
	}
	for _, p := range fallback {
		m[p] = true
	}
	return m
}

func main() {
	flag.Parse()
	if *versionOnlyFlag {
		fmt.Println(versionStr)
		return
	}
	if *versionFlag {
		fmt.Println("version:", versionStr)
		fmt.Println("built with: go1.26.0")
		fmt.Println("tag:", "v"+versionStr)
		fmt.Println("commit: n/a")
		fmt.Println("source: github.com/incu6us/goimports-reviser/v3")
		return
	}

	// Validate imports-order
	orderStr := strings.TrimSpace(*importsOrder)
	var order []string
	if orderStr == "" {
		order = []string{"std", "general", "company", "project"}
	} else {
		parts := strings.Split(*importsOrder, ",")
		// check each
		for _, p := range parts {
			t := strings.TrimSpace(p)
			if t != "std" && t != "general" && t != "company" && t != "project" && t != "blanked" && t != "dotted" {
				flag.Usage()
				log.Printf("unknown order group type: %q", t)
				os.Exit(1)
			}
		}
		// check contains at least std,general,company,project
		has := make(map[string]bool)
		for _, p := range parts {
			has[strings.TrimSpace(p)] = true
		}
		if !(has["std"] && has["general"] && has["company"] && has["project"]) {
			flag.Usage()
			log.Printf("use default at least 4 parameters to sort groups of your imports: %q", "std,general,company,project")
			os.Exit(1)
		}
		for _, p := range parts {
			order = append(order, strings.TrimSpace(p))
		}
	}

	// Build paths
	args := flag.Args()
	var paths []string
	paths = append(paths, args...)
	if *filePath != "" {
		paths = append(paths, *filePath)
	}
	if len(paths) == 0 {
		flag.Usage()
		log.Println("no file(s) or directory(ies) specified on input")
		os.Exit(1)
	}
	log.Printf("Paths: %v", paths)

	// Effective company prefixes (local quirk: only overwrite when both non-empty)
	effectiveCompany := *companyPrefixes
	if *localFlag != "" && *companyPrefixes != "" {
		effectiveCompany = *localFlag
	}
	var companyList []string
	if strings.TrimSpace(effectiveCompany) != "" {
		for _, c := range strings.Split(effectiveCompany, ",") {
			t := strings.TrimSpace(c)
			if t != "" {
				companyList = append(companyList, t)
			}
		}
	}

	// Process each path sequentially
	// For stdout+list-diff with multiple files, need global changed detection? Actually per earlier, if any changed, list all.
	// Simplify: process each path, collect results, handle output accordingly.
	// For single file paths, handle individually. For directory paths, handle via walk.
	// Need to track overall exit status for set-exit-status.
