						rest = fields[0]
					}
					if rest == "" {
						return "", fmt.Errorf("module is undefined")
					}
					return rest, nil
				}
			}
			return "", fmt.Errorf("module is undefined")
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return "", fmt.Errorf("open go.mod: no such file or directory")
}

func matchPrefix(path, prefix string) bool {
	p := strings.TrimSuffix(prefix, "/")
	if p == "" {
		return false
	}
	if path == p {
		return true
	}
	return strings.HasPrefix(path, p+"/")
}

func classifyImport(path, alias, project string, companies []string, hasBlanked, hasDotted bool) string {
	if alias == "_" && hasBlanked {
		return "blanked"
	}
	if alias == "." && hasDotted {
		return "dotted"
	}
	if project != "" && matchPrefix(path, project) {
		return "project"
	}
	for _, c := range companies {
		if matchPrefix(path, c) {
			return "company"
		}
	}
	if isStd(path) {
		return "std"
	}
	return "general"
}

func unquotePath(quoted string) string {
	s, err := strconv.Unquote(quoted)
	if err != nil {
		return strings.Trim(quoted, "\"`")
	}
	return s
}

func isVersioned(path string) bool {
	idx := strings.LastIndex(path, "/")
	if idx < 0 {
		return false
	}
	suffix := path[idx+1:]
	if len(suffix) < 2 || suffix[0] != 'v' {
		return false
	}
	for _, ch := range suffix[1:] {
		if ch < '0' || ch > '9' {
			return false
		}
	}
	return true
}
