	// Map line numbers (1-indexed) to indices.
	// For each gap from end, insert after endLine.
	// Process from last to first to keep indices stable.
	for i := len(ranges) - 2; i >= 0; i-- {
		endL := ranges[i].endLine
		posL := ranges[i+1].posLine
		if posL == endL+1 {
			// No blank, insert one empty line after endL (index endL, since lines[0] is line 1)
			idx := endL // lines index after endL (0-based: line endL is lines[endL-1], insert at endL)
			if idx >= 0 && idx <= len(lines) {
				lines = append(lines[:idx], append([]string{""}, lines[idx:]...)...)
				// Adjust subsequent ranges' line numbers
				for j := i + 1; j < len(ranges); j++ {
					ranges[j].posLine++
					ranges[j].endLine++
				}
			}
		}
	}
	return strings.Join(lines, "\n")
}
