type tmpImp struct {
	pathStr string
	alias   string
	rawPath string
	comment *ast.CommentGroup
	spec    *ast.ImportSpec
}

func formatContent(absPath, orig, project string, companies []string, order []string) (string, bool, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, absPath, orig, parser.ParseComments)
	if err != nil {
		return "", false, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %s", err.Error())
	}
	if !*applyToGenerated && isGeneratedFile(fset, f) {
		return orig, false, nil
	}
	var allSpecs []*ast.ImportSpec
	var genDecls []*ast.GenDecl
	for _, decl := range f.Decls {
		if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			genDecls = append(genDecls, gd)
			for _, sp := range gd.Specs {
				if is, ok := sp.(*ast.ImportSpec); ok {
					allSpecs = append(allSpecs, is)
				}
			}
		}
	}
	var imps []tmpImp
	for _, s := range allSpecs {
		raw := ""
		if s.Path != nil {
			raw = s.Path.Value
		}
		up := unquotePath(raw)
		alias := ""
		if s.Name != nil {
			alias = s.Name.Name
		}
		imps = append(imps, tmpImp{pathStr: up, alias: alias, rawPath: raw, comment: s.Comment, spec: s})
	}
	if *rmUnused || *setAlias {
		dir := filepath.Dir(absPath)
		var pkgErrs []string
		for _, imp := range imps {
			_, errStr, e := getPkgInfo(imp.pathStr, dir)
			if e != nil {
				pos := fset.Position(imp.spec.Path.Pos())
				base := filepath.Base(absPath)
				pkgErrs = append(pkgErrs, fmt.Sprintf("%s:%d:%d: %s", base, pos.Line, pos.Column, errStr))
			}
		}
		if len(pkgErrs) > 0 {
			for _, e := range pkgErrs {
				fmt.Fprintln(os.Stderr, e)
			}
			return "", false, fmt.Errorf("package has an errors")
		}
		if *setAlias {
			for i, imp := range imps {
				if imp.alias != "" {
					continue
				}
				if !isVersioned(imp.pathStr) {
					continue
				}
				pkgName, _, e := getPkgInfo(imp.pathStr, dir)
				if e != nil {
					continue
				}
				base := imp.pathStr[strings.LastIndex(imp.pathStr, "/")+1:]
				if pkgName != "" && pkgName != base && pkgName != "_" && pkgName != "." {
					imps[i].alias = pkgName
				}
			}
		}
		if *rmUnused {
			used := make(map[string]bool)
			for _, decl := range f.Decls {
				ast.Inspect(decl, func(n ast.Node) bool {
					if sel, ok := n.(*ast.SelectorExpr); ok {
						if id, ok := sel.X.(*ast.Ident); ok {
							used[id.Name] = true
						}
					}
					return true
				})
			}
			var filtered []tmpImp
			for _, imp := range imps {
				if imp.alias == "_" || imp.alias == "." {
					filtered = append(filtered, imp)
					continue
				}
				var checkNames []string
				if imp.alias != "" {
					checkNames = append(checkNames, imp.alias)
				} else {
					var base string
					if strings.Contains(imp.pathStr, "/") {
						base = imp.pathStr[strings.LastIndex(imp.pathStr, "/")+1:]
					} else {
						base = imp.pathStr
					}
					checkNames = append(checkNames, base)
					if isVersioned(imp.pathStr) {
						if pkgName, _, e := getPkgInfo(imp.pathStr, dir); e == nil && pkgName != "" && pkgName != base {
							checkNames = append(checkNames, pkgName)
						}
					} else {
						if !used[base] {
							if pkgName, _, e := getPkgInfo(imp.pathStr, dir); e == nil && pkgName != "" && pkgName != base {
								checkNames = append(checkNames, pkgName)
							}
						}
					}
				}
				keep := false
				for _, n := range checkNames {
					if used[n] {
						keep = true
						break
					}
				}
				if keep {
					filtered = append(filtered, imp)
				}
			}
			imps = filtered
		}
	}
	if len(imps) == 0 {
		var newDecls []ast.Decl
		for _, d := range f.Decls {
			if gd, ok := d.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
				continue
			}
			newDecls = append(newDecls, d)
		}
		f.Decls = newDecls
		var importRanges [][2]token.Pos
		for _, gd := range genDecls {
			if gd.Lparen.IsValid() && gd.Rparen.IsValid() {
				importRanges = append(importRanges, [2]token.Pos{gd.Lparen, gd.Rparen})
			} else {
				importRanges = append(importRanges, [2]token.Pos{gd.Pos(), gd.End()})
			}
		}
		var newComments []*ast.CommentGroup
		for _, cg := range f.Comments {
			inside := false
			for _, r := range importRanges {
				if cg.Pos() >= r[0] && cg.End() <= r[1] {
					inside = true
					break
				}
			}
			if !inside {
				newComments = append(newComments, cg)
			}
		}
		f.Comments = newComments
		var buf strings.Builder
		_ = buf
		var b2 bytes.Buffer
		_ = b2
		var buf2 bytes.Buffer
		if err := format.Node(&buf2, fset, f); err != nil {
			return "", false, err
		}
		out := buf2.String()
		if *formatFlag {
			out = applyFormatExtra(out)
		}
		return out, out != orig, nil
	}
	hasBlanked := false
	hasDotted := false
	for _, g := range order {
		if g == "blanked" {
			hasBlanked = true
		}
		if g == "dotted" {
			hasDotted = true
		}
	}
	grouped := make(map[string][]tmpImp)
	for _, imp := range imps {
		g := classifyImport(imp.pathStr, imp.alias, project, companies, hasBlanked, hasDotted)
		grouped[g] = append(grouped[g], imp)
	}
	for g := range grouped {
		sort.Slice(grouped[g], func(i, j int) bool {
			if grouped[g][i].pathStr != grouped[g][j].pathStr {
				return grouped[g][i].pathStr < grouped[g][j].pathStr
			}
			return grouped[g][i].alias < grouped[g][j].alias
		})
	}
	var ordered []tmpImp
	for _, g := range order {
		if lst, ok := grouped[g]; ok && len(lst) > 0 {
			ordered = append(ordered, lst...)
		}
	}
	tokFile := fset.File(f.Package)
	var firstPos, lastEnd token.Pos
	if len(genDecls) > 0 {
		firstPos = genDecls[0].Pos()
		lastEnd = genDecls[len(genDecls)-1].End()
	} else {
		firstPos = f.Package
		lastEnd = f.Package
	}
	firstOffset := tokFile.Offset(firstPos)
	lastOffset := tokFile.Offset(lastEnd)
	newBlock := buildImportBlock(grouped, order)
	singleNoParens := false
	if len(ordered) == 1 && len(genDecls) == 1 && !genDecls[0].Lparen.IsValid() {
		singleNoParens = true
		imp := ordered[0]
		var line string
		if imp.alias != "" {
			line = fmt.Sprintf("import %s %s", imp.alias, imp.rawPath)
		} else {
			line = fmt.Sprintf("import %s", imp.rawPath)
		}
		if imp.comment != nil {
			var ctexts []string
			for _, c := range imp.comment.List {
				ctexts = append(ctexts, c.Text)
			}
			line += " " + strings.Join(ctexts, " ")
		}
		newBlock = line
		_ = singleNoParens
	}
	_ = firstOffset
	_ = lastOffset
	_ = newBlock
	// Fallback: use AST manipulation + format.Node with position tricks for blank lines?
	// For now, implement via text replacement + format.Source
	before := orig[:firstOffset]
	after := orig[lastOffset:]
	if !singleNoParens {
		// newBlock already built with groups
	} else {
		// single line already
	}
	newSrc := before + newBlock + after
	formattedBytes, err := format.Source([]byte(newSrc))
	if err != nil {
		return "", false, fmt.Errorf("format error: %v", err)
	}
	out := string(formattedBytes)
	if *formatFlag {
		out = applyFormatExtra(out)
	}
	return out, out != orig, nil
}
