func isExcluded(absPath, baseDir, excludesStr string) bool {
	if strings.TrimSpace(excludesStr) == "" {
		return false
	}
	rel := ""
	if baseDir != "" {
		if r, err := filepath.Rel(baseDir, absPath); err == nil {
			rel = r
		}
	}
	if rel == "" {
		rel = absPath
	}
	// Normalize to slash for matching?
	relSlash := filepath.ToSlash(rel)
	absSlash := filepath.ToSlash(absPath)
	for _, pat := range strings.Split(excludesStr, ",") {
		p := strings.TrimSpace(pat)
		if p == "" {
			continue
		}
		pSlash := filepath.ToSlash(p)
		// Directory prefix (ends with /)
		if strings.HasSuffix(p, "/") {
			if strings.HasPrefix(relSlash, pSlash) || strings.HasPrefix(absSlash, pSlash) {
				return true
			}
			continue
		}
		// Ends with /* -> prefix without *
		if strings.HasSuffix(p, "/*") {
			prefix := strings.TrimSuffix(pSlash, "*")
			if strings.HasPrefix(relSlash, prefix) || strings.HasPrefix(absSlash, prefix) {
				return true
			}
			continue
		}
		if strings.HasSuffix(p, "/**") {
			prefix := strings.TrimSuffix(pSlash, "**")
			if strings.HasPrefix(relSlash, prefix) || strings.HasPrefix(absSlash, prefix) {
				return true
			}
			continue
		}
		if p == "**" {
			return true
		}
		// Contains glob?
		if strings.ContainsAny(p, "*?[\\") {
			if ok, _ := path.Match(pSlash, relSlash); ok {
				return true
			}
			if ok, _ := path.Match(pSlash, absSlash); ok {
				return true
			}
			// Also try filepath.Match?
			if ok, _ := filepath.Match(p, rel); ok {
				return true
			}
			if ok, _ := filepath.Match(p, absPath); ok {
				return true
			}
			continue
		}
		// No glob: prefix match (directory or exact file)
		if relSlash == pSlash || absSlash == pSlash {
			return true
		}
		if strings.HasPrefix(relSlash, pSlash+"/") || strings.HasPrefix(relSlash, pSlash) && pSlash == relSlash[:len(pSlash)] {
			// Check prefix with slash
			if strings.HasPrefix(relSlash, pSlash+"/") || relSlash == pSlash {
				return true
