func collectFiles(base string, recursive bool, excludesStr string) ([]string, error) {
	var files []string
	absBase, _ := filepath.Abs(base)
	if recursive {
		err := filepath.Walk(absBase, func(p string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}
			if info.IsDir() {
				// Check if dir excluded? For patterns like "a/b/" or "a", should skip walking?
				// If dir itself excluded, skip.
				rel, _ := filepath.Rel(absBase, p)
				if rel != "." {
					// Check excludes for dir: use abs path with base?
					// isExcluded expects file abs and baseDir; for dir, check with trailing slash?
					// Simplify: check if dir excluded via same logic (treat dir as file with trailing /?)
					// We'll check isExcluded for dir path (with base)
					if isExcluded(p, absBase, excludesStr) {
						return filepath.SkipDir
					}
				}
				return nil
			}
			if !strings.HasSuffix(p, ".go") {
				return nil
			}
			if isExcluded(p, absBase, excludesStr) {
				return nil
			}
			files = append(files, p)
			return nil
		})
		if err != nil {
			return nil, err
		}
	} else {
		entries, err := os.ReadDir(absBase)
		if err != nil {
			return nil, err
		}
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			if !strings.HasSuffix(e.Name(), ".go") {
				continue
			}
			p := filepath.Join(absBase, e.Name())
			if isExcluded(p, absBase, excludesStr) {
				continue
			}
			files = append(files, p)
		}
	}
	sort.Strings(files)
	return files, nil
}

